1	import { createHash } from "node:crypto";
2	import { db } from "@/lib/db";
3	import { isMailConfigured, sendMail } from "@/lib/mail";
4	import { appUrl } from "@/lib/notifications/templates";
5	import { bareHost, siteHostAllowed } from "@/app/api/site/[slug]/site-host";
6	
7	// =============================================================================
8	// FORM SUBMISSIONS FROM PUBLISHED GENERATED SITES
9	// =============================================================================
10	//
11	// The one deliberate hole in "generated sites have no backend". The generated
12	// page stays completely static — no fetch, no JSON, no client state, nothing
13	// that `connect-src 'none'` would have to be relaxed for. A plain
14	// `<form method="post" action="/__forms/contact">` navigates the browser, and
15	// only the POST TARGET is ours.
16	//
17	// WHY THE TARGET IS THE SITE'S OWN ORIGIN, NOT kodely.me
18	// ------------------------------------------------------
19	// The generated document is served with `form-action 'self'`, and `'self'`
20	// resolves to the DOCUMENT's origin — `https://<slug>.kodely.site` — not to
21	// ours. The obvious design (post to `https://kodely.me/api/forms/...`) is
22	// therefore cross-origin and would require widening that directive to name an
23	// external origin on every customer site on the platform.
24	//
25	// It is not needed, because `<slug>.kodely.site` is already us. proxy.ts
26	// rewrites every request on that host to `/api/site/<slug>/…`, so a form
27	// posting to its own origin at `/__forms/<name>` lands in the same Next route
28	// that served the page. Same origin, same app, same database — and
29	// `form-action 'self'` permits it unchanged. See the header comments in
30	// app/api/site/[slug]/[[...path]]/route.ts.
31	//
32	// WHAT IS UNTRUSTED HERE
33	// ----------------------
34	// Everything in the body. It is stored as JSON, rendered only by React (which
35	// escapes), only ever queried through Prisma's parameter binding, capped at
36	// write time, and escaped again on the way into the notification email —
37	// where nothing submitted may reach a header except one strictly-validated
38	// address (see replyToFor).
39	
40	const SITES_BASE = (process.env.KODELY_SITES_BASE ?? "kodely.site").trim().toLowerCase();
41	
42	/** First path segment of a submission URL: `/__forms/<formName>`. */
43	export const FORM_PATH_SEGMENT = "__forms";
44	
45	// ── Hard caps ────────────────────────────────────────────────────────────────
46	//
47	// The body cap is the binding one: 12 × 5000 characters could not fit in 32 KB,
48	// so no combination of the per-field caps can produce a row larger than the
49	// body we were willing to read. Everything is checked BEFORE the write, and an
50	// over-cap request is refused rather than silently truncated — quietly dropping
51	// half of someone's enquiry is the same failure mode this whole feature exists
52	// to remove.
53	
54	/** Bytes of request body ever read. Anything larger is refused unread. */
55	const MAX_BODY_BYTES = 32 * 1024;
56	/** Stored fields, excluding `_`-prefixed control fields. */
57	const MAX_FIELDS = 12;
58	const MAX_KEY_LENGTH = 64;
59	const MAX_VALUE_LENGTH = 5000;
60	/** A form name is part of a URL and is stored; keep it boring. */
61	const FORM_NAME_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;
62	/** Field names the builder may emit. Rejecting anything else keeps the stored
63	 *  JSON's key space to identifiers, so no key can collide with object
64	 *  internals or need escaping anywhere downstream. */
65	const FIELD_NAME_RE = /^[A-Za-z][A-Za-z0-9_-]{0,63}$/;
66	
67	// ── Rate limits ──────────────────────────────────────────────────────────────
68	//
69	// Three layers, cheapest first, because this endpoint is unauthenticated and
70	// reachable by anyone who can resolve a customer's subdomain:
71	//
72	//  1. an in-process burst limiter, keyed on the hashed IP, that costs no query
73	//     at all — it sheds a flood before the database is touched;
74	//  2. durable per-IP limits, counted from the rows this feature already writes
75	//     (the same shape as checkGenerateRateLimit in lib/rate-limit.ts);
76	//  3. durable per-project limits, which bound how much one site can be made to
77	//     store and how much mail one owner can be made to receive.
78	//
79	// Layers 2 and 3 count STORED submissions, so a refused request costs nothing
80	// and adds nothing — an attacker who trips a bucket writes no further rows.
81	// The honest consequence: a caller who is refused for some other reason (bad
82	// honeypot excepted — those are stored) can keep asking, and is bounded only
83	// by layer 1. That is a request-rate problem, not a storage problem, and layer
84	// 1 is a per-process speed bump rather than a guarantee. See RESIDUALS below.
85	
86	const BURST_LIMIT = 8;
87	const BURST_WINDOW_MS = 5 * 60_000;
88	
89	const IP_HOUR_LIMIT = 15;
90	const IP_DAY_LIMIT = 50;
91	
92	const PROJECT_HOUR_LIMIT = 60;
93	const PROJECT_DAY_LIMIT = 300;
94	
95	/** Above this many submissions to one project in an hour, stop emailing and
96	 *  let the owner read them in the app. A flood must not become an inbox flood. */
97	const EMAIL_MAX_PER_HOUR = 10;
98	
99	/** A form filled in faster than this by something claiming to be a human is
100	 *  almost certainly not one. Advisory only — see `_t` in the markup contract. */
101	const MIN_FILL_MS = 2_000;
102	
103	// ── IP handling ──────────────────────────────────────────────────────────────
104	
105	/**
106	 * The client address, or the shared bucket for traffic that did not come
107	 * through the edge.
108	 *
109	 * Identical reasoning to clientIp() in lib/rate-limit.ts, which cannot be
110	 * imported (that file is not mine to change and does not export it): only
111	 * `cf-connecting-ip` is trustworthy here. Cloudflare sets it on every request,
112	 * overwriting whatever the client sent. `x-forwarded-for`'s first entry is
113	 * attacker-chosen — Cloudflare APPENDS rather than replaces — so keying on it
114	 * hands an attacker a fresh bucket per request and the limiter does nothing.
115	 * (app/api/contact/route.ts still does exactly that; this does not copy it.)
116	 *
117	 * No header ⇒ direct-to-origin or local dev ⇒ one shared, strict bucket.
118	 * Fails closed: such traffic is throttled collectively, never exempted.
119	 */
120	function clientIp(req: Request): string {
121	  return req.headers.get("cf-connecting-ip")?.trim().toLowerCase() || "no-edge";
122	}
123	
124	/**
125	 * What actually gets stored. A raw visitor IP on a contact-form row is personal
126	 * data the site owner has no need for and we have no reason to hold; a salted
127	 * digest still supports rate limiting and abuse triage and is useless for
128	 * anything else. Stable across restarts on purpose — a per-process salt would
129	 * hand every address a fresh bucket on each deploy.
130	 */
131	const IP_SALT = process.env.FORM_IP_SALT ?? "kodely:form-submission:v1";
132	function hashIp(ip: string): string {
133	  return createHash("sha256").update(`${IP_SALT}:${ip}`).digest("hex");
134	}
135	
136	// ── Layer 1: in-process burst limiter ────────────────────────────────────────
137	
138	const burst = new Map<string, number[]>();
139	const BURST_MAX_KEYS = 20_000;
140	
141	/**
142	 * Bound the map without ever letting a flood of unique keys wipe it.
143	 *
144	 * Deliberately NOT the wholesale `clear()` used by checkEnhanceRateLimit and
145	 * app/api/contact/route.ts: those guard authenticated or low-value paths, while
146	 * here a clear would be a documented way for an attacker to reset the counter
147	 * that is throttling them. Expired entries go first, then the least recently
148	 * active — an attacker's own bucket is the most recently active, so it is the
149	 * last thing evicted. Same reasoning as sweep() in lib/rate-limit.ts.
150	 */
151	function sweepBurst(now: number): void {
152	  if (burst.size <= BURST_MAX_KEYS) return;
153	  for (const [key, hits] of burst) {
154	    if (hits.length === 0 || hits[hits.length - 1] <= now - BURST_WINDOW_MS) burst.delete(key);
155	  }
156	  if (burst.size <= BURST_MAX_KEYS) return;
157	  const byLastSeen = [...burst.entries()].sort(
158	    (a, b) => a[1][a[1].length - 1] - b[1][b[1].length - 1],
159	  );
160	  for (const [key] of byLastSeen.slice(0, burst.size - BURST_MAX_KEYS)) burst.delete(key);
161	}
162	
163	function burstLimited(ipHash: string): boolean {
164	  const now = Date.now();
165	  sweepBurst(now);
166	  const recent = (burst.get(ipHash) ?? []).filter((t) => t > now - BURST_WINDOW_MS);
167	  if (recent.length >= BURST_LIMIT) {
168	    burst.set(ipHash, recent);
169	    return true;
170	  }
171	  recent.push(now);
172	  burst.set(ipHash, recent);
173	  return false;
174	}
175	
176	// ── Parsing ──────────────────────────────────────────────────────────────────
177	
178	/**
179	 * Read at most `MAX_BODY_BYTES`, then stop.
180	 *
181	 * `await req.text()` would buffer whatever was sent, and Content-Length is a
182	 * claim by the caller, not a fact — so the length header is only used as a fast
183	 * pre-check and the stream is counted as it arrives. Returns null when the cap
184	 * is passed, and cancels the rest rather than draining it.
185	 */
186	async function readCapped(req: Request): Promise<string | null> {
187	  const declared = Number(req.headers.get("content-length") ?? "");
188	  if (Number.isFinite(declared) && declared > MAX_BODY_BYTES) return null;
189	
190	  const body = req.body;
191	  if (!body) return "";
192	
193	  const reader = body.getReader();
194	  const chunks: Buffer[] = [];
195	  let total = 0;
196	  let done = false;
197	  while (!done) {
198	    const next = await reader.read();
199	    done = next.done;
200	    if (next.value) {
201	      total += next.value.byteLength;
202	      if (total > MAX_BODY_BYTES) {
203	        await reader.cancel().catch(() => undefined);
204	        return null;
205	      }
206	      chunks.push(Buffer.from(next.value));
207	    }
208	  }
209	  return Buffer.concat(chunks).toString("utf8");
210	}
211	
212	/** Collapse control characters, normalise newlines, trim. Never HTML-escapes:
213	 *  escaping belongs at each output boundary, not in storage, or the stored
214	 *  value stops being what the visitor typed. */
215	function cleanValue(raw: string): string {
216	  return raw
217	    .replace(/\r\n?/g, "\n")
218	    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
219	    .trim();
220	}
221	
222	type ParsedBody =
223	  | { ok: true; fields: Record<string, string>; control: Record<string, string> }
224	  | { ok: false; status: number; message: string };
225	
226	function parseFields(raw: string): ParsedBody {
227	  let params: URLSearchParams;
228	  try {
229	    params = new URLSearchParams(raw);
230	  } catch {
231	    return { ok: false, status: 400, message: "That form could not be read." };
232	  }
233	
234	  const fields: Record<string, string> = {};
235	  const control: Record<string, string> = {};
236	  const seen = new Set<string>();
237	
238	  for (const key of params.keys()) {
239	    if (seen.has(key)) continue;
240	    seen.add(key);
241	
242	    if (key.length > MAX_KEY_LENGTH) {
243	      return { ok: false, status: 400, message: "That form has an unexpected field." };
244	    }
245	
246	    // `_`-prefixed names are control fields: the honeypot, the timing token,
247	    // the post-submit destination. They are never stored and never emailed,
248	    // which is also what keeps the honeypot's value out of the owner's inbox.
249	    if (key.startsWith("_")) {
250	      control[key] = cleanValue(params.get(key) ?? "").slice(0, 200);
251	      continue;
252	    }
253	
254	    if (!FIELD_NAME_RE.test(key)) {
255	      return { ok: false, status: 400, message: "That form has an unexpected field." };
256	    }
257	
258	    // Repeated names (a checkbox group) collapse to one field, not many.
259	    const value = cleanValue(params.getAll(key).join(", "));
260	    if (value.length > MAX_VALUE_LENGTH) {
261	      return {
262	        ok: false,
263	        status: 413,
264	        message: `One of those answers is too long (${MAX_VALUE_LENGTH} characters max).`,
265	      };
266	    }
267	    if (value === "") continue;
268	
269	    if (Object.keys(fields).length >= MAX_FIELDS) {
270	      return { ok: false, status: 400, message: "That form has too many fields." };
271	    }
272	    fields[key] = value;
273	  }
274	
275	  if (Object.keys(fields).length === 0) {
276	    return { ok: false, status: 400, message: "Please fill in the form before sending it." };
277	  }
278	  return { ok: true, fields, control };
279	}
280	
281	// ── Responses ────────────────────────────────────────────────────────────────
282	//
283	// A native form POST is a NAVIGATION: whatever comes back is what the visitor
284	// sees. So every reply here is a small, self-contained HTML page rather than
285	// JSON, and it echoes nothing that was submitted.
286	
287	function escapeHtml(value: string): string {
288	  return value
289	    .replace(/&/g, "&amp;")
290	    .replace(/</g, "&lt;")
291	    .replace(/>/g, "&gt;")
292	    .replace(/"/g, "&quot;")
293	    .replace(/'/g, "&#39;");
294	}
295	
296	// Our own page, not the customer's, so it gets its own policy rather than
297	// SANDBOX_CSP: it needs nothing but inline styles and must never be framed.
298	const REPLY_CSP =
299	  "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
300	
301	function page(status: number, title: string, body: string, backHref: string): Response {
302	  const html = `<!doctype html>
303	<html lang="en">
304	  <head>
305	    <meta charset="utf-8">
306	    <meta name="viewport" content="width=device-width,initial-scale=1">
307	    <meta name="robots" content="noindex">
308	    <title>${escapeHtml(title)}</title>
309	  </head>
310	  <body style="margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:#f6f7f8;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111111;">
311	    <main style="max-width:420px;text-align:center;">
312	      <h1 style="margin:0 0 12px 0;font-size:20px;font-weight:600;letter-spacing:-0.01em;">${escapeHtml(title)}</h1>
313	      <p style="margin:0 0 20px 0;font-size:15px;line-height:1.6;color:#4b5563;">${escapeHtml(body)}</p>
314	      <a href="${escapeHtml(backHref)}" style="display:inline-block;padding:10px 18px;background:#111111;color:#ffffff;text-decoration:none;border-radius:8px;font-size:15px;font-weight:600;">Back to the site</a>
315	    </main>
316	  </body>
317	</html>
318	`;
319	  return new Response(html, {
320	    status,
321	    headers: {
322	      "Content-Type": "text/html; charset=utf-8",
323	      "Content-Security-Policy": REPLY_CSP,
324	      "X-Content-Type-Options": "nosniff",
325	      "Referrer-Policy": "no-referrer",
326	      "Cache-Control": "no-store",
327	    },
328	  });
329	}
330	
331	/**
332	 * The reply for "this site does not exist, is not published, or you are asking
333	 * from a host that may not serve it".
334	 *
335	 * One response for all three on purpose, and byte-compatible in meaning with
336	 * the GET handler's 404: a caller probing for which slugs exist, or which are
337	 * published, learns nothing from the difference.
338	 */
339	function notFound(): Response {
340	  return new Response("Site not found.", {
341	    status: 404,
342	    headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" },
343	  });
344	}
345	
346	/**
347	 * Where "Back to the site" and `_next` point.
348	 *
349	 * On the branded subdomain the site is at `/`. On the staging path form
350	 * (staging.kodely.me/api/site/<slug>/ — see site-host.ts) it is one directory
351	 * deep, and a bare `/` would leave the customer's site entirely.
352	 */
353	function siteBase(host: string, slug: string): string {
354	  return bareHost(host) === `${slug}.${SITES_BASE}` ? "/" : `/api/site/${slug}/`;
355	}
356	
357	/**
358	 * An optional post-submit destination, resolved against the site's own base.
359	 *
360	 * Only a path, never a URL: it must start with a single `/`, and `//evil.example`
361	 * (a protocol-relative URL, which is a cross-origin redirect wearing a path's
362	 * clothes) is rejected along with anything carrying a scheme or a backslash.
363	 * So this cannot become an open redirect, whatever the builder emits.
364	 */
365	function nextPath(control: Record<string, string>, base: string): string | null {
366	  const raw = control._next;
367	  if (!raw) return null;
368	  if (!/^\/[A-Za-z0-9\-._~!$&'()*+,;=:@%/?#]*$/.test(raw)) return null;
369	  if (raw.startsWith("//")) return null;
370	  return `${base}${raw.slice(1)}`;
371	}
372	
373	// ── Notification email ───────────────────────────────────────────────────────
374	//
375	// Same rules as lib/notifications/templates.ts, and for the same reasons: plain
376	// text is the real message, the HTML alternative is built from the same values,
377	// nothing remote is referenced, and every interpolated value is escaped. The
378	// composer is local rather than imported because that module's Block/compose
379	// helpers are private to it and its EmailKind union has no member for this —
380	// adding one would mean editing a file that is not mine.
381	
382	/** CR/LF can never reach a mail header. lib/mail.ts has a private headerSafe()
383	 *  for exactly this; it is not exported, so this is the same guard restated. */
384	function headerSafe(value: string, max = 200): string {
385	  return value.replace(/[\r\n]+/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
386	}
387	
388	/**
389	 * A Reply-To built from visitor input, or nothing.
390	 *
391	 * This is the single place where submitted content reaches a mail HEADER, so it
392	 * is the single place header injection could happen. The regex admits no CR, no
393	 * LF, no comma, no semicolon, no angle bracket and no quote, so a value that
394	 * passes cannot terminate the header or start another one — and the display
395	 * name is dropped entirely rather than sanitised, because a bare address needs
396	 * no quoting rules to be got right. Anything that does not match is simply not
397	 * used; the field still appears in the body, where it is only text.
398	 *
399	 * From is never the visitor: sending as their domain fails its SPF/DMARC. Same
400	 * reasoning as sendContactEmail() in lib/mail.ts, and sendMail() enforces it.
401	 */
402	const STRICT_EMAIL_RE = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]{1,64}@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/;
403	
404	function replyToFor(fields: Record<string, string>): string | undefined {
405	  const candidate = fields.email ?? fields.Email ?? "";
406	  if (candidate.length > 200) return undefined;
407	  return STRICT_EMAIL_RE.test(candidate) ? candidate : undefined;
408	}
409	
410	function submissionEmail(input: {
411	  projectName: string;
412	  projectId: string;
413	  formName: string;
414	  fields: Record<string, string>;
415	}): { subject: string; text: string; html: string } {
416	  const name = headerSafe(input.projectName, 80) || "your site";
417	  const inbox = `${appUrl()}/projects/${encodeURIComponent(input.projectId)}/submissions`;
418	  const entries = Object.entries(input.fields);
419	
420	  const text = [
421	    `Someone filled in the "${headerSafe(input.formName, 32)}" form on ${name}.`,
422	    "",
423	    ...entries.map(([k, v]) => `${k}:\n${v}`),
424	    "",
425	    `All submissions: ${inbox}`,
426	    "",
427	    "--",
428	    "You're receiving this because it concerns your own Kodely account.",
429	    "We only send email about your account — never marketing.",
430	  ].join("\n");
431	
432	  const rows = entries
433	    .map(
434	      ([k, v]) =>
435	        `<tr><td style="padding:6px 12px 6px 0;vertical-align:top;font-size:13px;color:#6b7280;white-space:nowrap;">${escapeHtml(
436	          k,
437	        )}</td><td style="padding:6px 0;font-size:15px;line-height:1.6;color:#111111;white-space:pre-wrap;">${escapeHtml(
438	          v,
439	        )}</td></tr>`,
440	    )
441	    .join("");
442	
443	  const html = `<!doctype html>
444	<html lang="en">
445	  <head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New form submission</title></head>
446	  <body style="margin:0;padding:24px;background:#f6f7f8;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111111;">
447	    <div style="max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:28px;">
448	      <p style="margin:0 0 20px 0;font-size:14px;font-weight:600;letter-spacing:-0.01em;color:#111111;">kodely</p>
449	      <p style="margin:0 0 16px 0;font-size:15px;line-height:1.6;">Someone filled in the &quot;${escapeHtml(
450	        input.formName,
451	      )}&quot; form on ${escapeHtml(name)}.</p>
452	      <table style="width:100%;border-collapse:collapse;margin:0 0 20px 0;">${rows}</table>
453	      <p style="margin:0;"><a href="${escapeHtml(
454	        inbox,
455	      )}" style="display:inline-block;padding:10px 18px;background:#111111;color:#ffffff;text-decoration:none;border-radius:8px;font-size:15px;font-weight:600;">All submissions</a></p>
456	      <p style="margin:24px 0 0 0;padding-top:16px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.5;color:#6b7280;">You&#39;re receiving this because it concerns your own Kodely account. We only send email about your account — never marketing.</p>
457	    </div>
458	  </body>
459	</html>
460	`;
461	
462	  return { subject: `New ${headerSafe(input.formName, 32)} submission — ${name}`, text, html };
463	}
464	
465	/**
466	 * Best effort, always. The submission is already committed before this is
467	 * called and nothing here can undo that: a dead SMTP server, a bad address or a
468	 * hung connection loses an email, never an enquiry. Same guarantee as
469	 * lib/notifications/send.ts, which is why this returns void and swallows.
470	 */
471	function notifyOwner(input: {
472	  to: string;
473	  projectName: string;
474	  projectId: string;
475	  formName: string;
476	  fields: Record<string, string>;
477	}): void {
478	  if (process.env.KODELY_NOTIFY_DISABLED === "1") return;
479	  if (!isMailConfigured()) return;
480	
481	  const email = submissionEmail(input);
482	  const replyTo = replyToFor(input.fields);
483	
484	  void sendMail({
485	    to: input.to,
486	    subject: headerSafe(email.subject, 200),
487	    ...(replyTo ? { replyTo } : {}),
488	    text: email.text,
489	    html: email.html,
490	  }).catch((err) => {
491	    // Never the body, never the visitor's address — just that it failed.
492	    console.error("[site-forms] notification send failed:", err);
493	  });
494	}
495	
496	// ── The endpoint ─────────────────────────────────────────────────────────────
497	
498	/**
499	 * Handle `POST /__forms/<formName>` from a published generated site.
500	 *
501	 * Called from app/api/site/[slug]/[[...path]]/route.ts, which is where the
502	 * subdomain rewrite lands. `path` is the already-split catch-all.
503	 */
504	export async function submitSiteForm(
505	  req: Request,
506	  slug: string,
507	  path: string[],
508	): Promise<Response> {
509	  const host = req.headers.get("host") ?? "";
510	
511	  // Same gate as GET, and for the same reason: the proxy is explicit that it is
512	  // never the only check, and a POST that stores data is the last place to rely
513	  // on one. A wrong host is indistinguishable from a missing site.
514	  if (!siteHostAllowed(host, slug)) return notFound();
515	
516	  if (path.length !== 2 || path[0] !== FORM_PATH_SEGMENT) return notFound();
517	  const formName = path[1].toLowerCase();
518	  if (!FORM_NAME_RE.test(formName)) return notFound();
519	
520	  const base = siteBase(host, slug);
521	
522	  // A browser always sends Origin on a cross-document POST, and for a form on
523	  // the site itself it is the site's own origin. Requiring it costs nothing and
524	  // turns away the simplest scripted floods and any other page trying to post
525	  // here on a visitor's behalf. It is FORGEABLE by anything that is not a
526	  // browser — this is a filter, not an authorisation check, and nothing below
527	  // depends on it being true.
528	  const origin = req.headers.get("origin");
529	  if (!origin) {
530	    return page(403, "That didn't send", "This form has to be submitted from the site itself.", base);
531	  }
532	  let originHost: string;
533	  try {
534	    originHost = new URL(origin).host;
535	  } catch {
536	    return page(403, "That didn't send", "This form has to be submitted from the site itself.", base);
537	  }
538	  if (!siteHostAllowed(originHost, slug)) {
539	    return page(403, "That didn't send", "This form has to be submitted from the site itself.", base);
540	  }
541	
542	  // Only the encoding a plain HTML form produces. multipart exists for file
543	  // uploads, which this does not accept and must not be made to buffer; JSON
544	  // would mean a scripted caller, which `connect-src 'none'` already forbids
545	  // the page itself from being.
546	  const contentType = (req.headers.get("content-type") ?? "").split(";")[0].trim().toLowerCase();
547	  if (contentType !== "application/x-www-form-urlencoded") {
548	    return page(415, "That didn't send", "This form was submitted in a format we don't accept.", base);
549	  }
550	
551	  const ipHash = hashIp(clientIp(req));
552	
553	  // Layer 1, before anything touches the database.
554	  if (burstLimited(ipHash)) {
555	    return page(429, "Too many messages", "Please wait a few minutes and try again.", base);
556	  }
557	
558	  const raw = await readCapped(req);
559	  if (raw === null) {
560	    return page(413, "That message is too long", "Please shorten it and try again.", base);
561	  }
562	
563	  const parsed = parseFields(raw);
564	  if (!parsed.ok) return page(parsed.status, "That didn't send", parsed.message, base);
565	  const { fields, control } = parsed;
566	
567	  const project = await db.project.findUnique({
568	    where: { slug },
569	    select: {
570	      id: true,
571	      name: true,
572	      publishedAt: true,
573	      user: { select: { email: true } },
574	    },
575	  });
576	  // PUBLISHED only. A draft site is not reachable on this host anyway, but the
577	  // storage decision is made here, not inferred from routing.
578	  if (!project || !project.publishedAt) return notFound();
579	
580	  // Layers 2 and 3. Two bounded reads rather than four counts: the day window
581	  // contains the hour window, and `take` caps the work at one row past the
582	  // limit that would already have refused the request.
583	  const now = Date.now();
584	  const dayAgo = new Date(now - 24 * 60 * 60_000);
585	  const hourAgo = now - 60 * 60_000;
586	  const [ipRows, projectRows] = await Promise.all([
587	    db.formSubmission.findMany({
588	      where: { ipHash, createdAt: { gte: dayAgo } },
589	      select: { createdAt: true },
590	      orderBy: { createdAt: "desc" },
591	      take: IP_DAY_LIMIT + 1,
592	    }),
593	    db.formSubmission.findMany({
594	      where: { projectId: project.id, createdAt: { gte: dayAgo } },
595	      select: { createdAt: true },
596	      orderBy: { createdAt: "desc" },
597	      take: PROJECT_DAY_LIMIT + 1,
598	    }),
599	  ]);
600	  const inHour = (rows: { createdAt: Date }[]) =>
601	    rows.filter((r) => r.createdAt.getTime() > hourAgo).length;
602	  const ipHour = inHour(ipRows);
603	  const projectHour = inHour(projectRows);
604	
605	  if (ipHour >= IP_HOUR_LIMIT || ipRows.length >= IP_DAY_LIMIT) {
606	    return page(429, "Too many messages", "Please try again later.", base);
607	  }
608	  if (projectHour >= PROJECT_HOUR_LIMIT || projectRows.length >= PROJECT_DAY_LIMIT) {
609	    // Deliberately the same wording as the per-IP refusal: a visitor should not
610	    // be told that somebody else has filled this site's quota.
611	    return page(429, "Too many messages", "Please try again later.", base);
612	  }
613	
614	  // Honeypot: a field no human can see, so anything in it is automation. The
615	  // row is KEPT and flagged rather than dropped — the schema's own comment asks
616	  // for that, so a false positive is recoverable and the rate is measurable —
617	  // and it still consumes quota, so flagging is not a cheap way to write rows.
618	  const trapped = (control._gotcha ?? "") !== "";
619	
620	  // Timing, advisory: only ever a verdict when the token is present and sane.
621	  // The page is static and cached, so this can only be set by the tiny inline
622	  // script in the markup contract; a no-JS visitor sends nothing and is judged
623	  // on the honeypot alone.
624	  const startedAt = Number(control._t ?? "");
625	  const tooFast =
626	    Number.isFinite(startedAt) &&
627	    startedAt > now - 24 * 60 * 60_000 &&
628	    startedAt <= now &&
629	    now - startedAt < MIN_FILL_MS;
630	
631	  const spam = trapped || tooFast;
632	
633	  await db.formSubmission.create({
634	    data: { projectId: project.id, formName, fields, ipHash, spam },
635	  });
636	
637	  // Email AFTER the write, and never awaited. Flagged submissions are stored
638	  // but not delivered, and a project already receiving a lot this hour stops
639	  // generating mail rather than turning a form flood into an inbox flood.
640	  if (!spam && project.user.email && projectHour < EMAIL_MAX_PER_HOUR) {
641	    notifyOwner({
642	      to: project.user.email,
643	      projectName: project.name,
644	      projectId: project.id,
645	      formName,
646	      fields,
647	    });
648	  }
649	
650	  const target = nextPath(control, base);
651	  if (target) {
652	    // 303: the follow-up is a GET, so a refresh cannot resubmit.
653	    return new Response(null, {
654	      status: 303,
655	      headers: { Location: target, "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" },
656	    });
657	  }
658	
659	  // A spam-flagged submitter gets the ordinary reply: telling a bot it was
660	  // caught only teaches it to try another shape.
661	  return page(200, "Thanks — that's been sent", "We'll get back to you shortly.", base);
662	}
663	
664	// ── RESIDUALS ────────────────────────────────────────────────────────────────
665	//
666	// Stated rather than hidden:
667	//
668	//  * A caller who can reach the origin IP directly, bypassing Cloudflare, can
669	//    forge `cf-connecting-ip` and get a fresh bucket per request. No
670	//    application code can detect that; the fix is an origin firewall limited to
671	//    Cloudflare's ranges. Same residual lib/rate-limit.ts documents.
672	//  * The in-process burst limiter is per-process and resets on deploy, so it
673	//    multiplies by the process count and is a speed bump, not a guarantee. The
674	//    durable limits behind it are what actually bound storage and mail.
675	//  * `Origin` is trivially forged by a non-browser client.
676	//  * Refused requests write nothing, so they are not counted by the durable
677	//    limits — an attacker can keep making requests that are refused, which
678	//    costs reads. The burst limiter is the only thing bounding that.
679	//  * The per-IP count has no dedicated index (the schema is fixed); it is a
680	//    bounded range scan of FormSubmission_createdAt_idx.
681	//  * Nothing here classifies CONTENT. A submission can be abusive text and pass
682	//    every check, exactly as lib/rate-limit.ts says of generated sites.
