146	                </Button>
147	                <Button
148	                  size="xs"
149	                  variant="ghost"
150	                  disabled={busy}
151	                  onClick={() => void patch({ ids: [r.id], spam: !r.spam })}
152	                >
153	                  {r.spam ? "Not spam" : "Mark spam"}
154	                </Button>
155	              </div>
156	              {r.fields.length === 0 ? (
