4	export const dynamic = "force-dynamic";
5	
6	// Owner-side triage for form submissions. The PUBLIC write endpoint is not
7	// here — it lives on the site's own origin, in
8	// app/api/site/[slug]/[[...path]]/route.ts, because that is the only origin a
9	// generated page is allowed to POST to (see lib/site-forms.ts). This route is
10	// the opposite: authenticated, first-party, and it never creates anything.
11	
12	/** Ceiling on ids per call, so one request can't ask for an unbounded IN list. */
13	const MAX_IDS = 500;
14	
15	function idList(value: unknown): string[] | null | undefined {
16	  if (value === undefined) return undefined; // "all of them"
17	  if (!Array.isArray(value)) return null;
18	  if (value.length === 0 || value.length > MAX_IDS) return null;
19	  if (!value.every((v) => typeof v === "string" && v.length > 0 && v.length <= 64)) return null;
20	  return value as string[];
21	}
22	
23	/**
24	 * Mark submissions read/unread, or flag/unflag them as spam.
25	 *
26	 * Ownership is established once, against the project, and every update is then
27	 * scoped by `projectId` — so an id belonging to somebody else's project simply
28	 * matches nothing. A wrong-owner project id is a 404, indistinguishable from a
29	 * project that does not exist.
30	 */
31	export async function PATCH(req: Request, { params }: { params: Promise<{ projectId: string }> }) {
32	  const user = await requireUser().catch(() => null);
33	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
34	  const { projectId } = await params;
35	
36	  const body = (await req.json().catch(() => null)) as
37	    | { ids?: unknown; read?: unknown; spam?: unknown }
38	    | null;
39	  if (!body) return Response.json({ error: "Invalid request." }, { status: 400 });
40	
41	  const ids = idList(body.ids);
42	  if (ids === null) return Response.json({ error: "Invalid request." }, { status: 400 });
43	
44	  const read = body.read;
45	  const spam = body.spam;
46	  if (read !== undefined && typeof read !== "boolean") {
47	    return Response.json({ error: "Invalid request." }, { status: 400 });
48	  }
49	  if (spam !== undefined && typeof spam !== "boolean") {
50	    return Response.json({ error: "Invalid request." }, { status: 400 });
51	  }
52	  if (read === undefined && spam === undefined) {
53	    return Response.json({ error: "Nothing to change." }, { status: 400 });
54	  }
55	
56	  const project = await db.project.findFirst({
57	    where: { id: projectId, userId: user.id },
58	    select: { id: true },
59	  });
60	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
61	
62	  const data: { readAt?: Date | null; spam?: boolean } = {};
63	  // readAt is a timestamp, not a flag: "unread" is null, and re-marking an
64	  // already-read submission does not move its timestamp (the filter below).
65	  if (read === true) data.readAt = new Date();
66	  if (read === false) data.readAt = null;
67	  if (spam !== undefined) data.spam = spam;
68	
69	  const { count } = await db.formSubmission.updateMany({
70	    where: {
71	      projectId: project.id,
72	      ...(ids ? { id: { in: ids } } : {}),
73	      // Only when read is the ONLY change: combining it with a spam flag would
74	      // otherwise silently skip the already-read rows the caller asked about.
75	      ...(read === true && spam === undefined ? { readAt: null } : {}),
76	    },
77	    data,
78	  });
79	
80	  return Response.json({ ok: true, updated: count });
81	}
