    limited(key: string): boolean {
      const now = Date.now();
      sweep(now);
      const recent = (hits.get(key) ?? []).filter((t) => t > now - opts.windowMs);
      if (recent.length >= opts.limit) {
        hits.set(key, recent);
        return true;
      }
