import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { ButtonLink } from "@/components/ui/Button";
import { EmptyState } from "@/components/ui/EmptyState";
import RecordList, { type RecordRow } from "./RecordList";

export const dynamic = "force-dynamic";

/** Newest page of records. Enough for every real inbox; see the note below. */
const PAGE_SIZE = 200;

/**
 * Everything a published site has written back through `/__records/<kind>`
 * (lib/site-records.ts) — the generic storage primitive behind future
 * backend-backed site features.
 *
 * `kind` is whatever string a generated site chose (a booking, a listing, a
 * CRM row, anything) — never a fixed enum, so this page groups and filters by
 * whatever kinds actually exist for THIS project rather than a hardcoded
 * list. `fields` is UNTRUSTED PUBLIC INPUT — anyone who can load the site can
 * put anything in it. It is rendered as React children and never as HTML:
 * there is no dangerouslySetInnerHTML anywhere on this page or in RecordList,
 * so a record containing markup is displayed as the text it is. That is the
 * whole defence and it must stay that way.
 */
export default async function RecordsPage({ params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");
  const { id } = await params;

  const project = await db.project.findFirst({
    where: { id, userId: user.id },
    select: { id: true, name: true, slug: true, publishedAt: true },
  });
  if (!project) redirect("/dashboard");

  const [rows, total, kindCounts] = await Promise.all([
    db.siteRecord.findMany({
      where: { projectId: project.id },
      orderBy: { createdAt: "desc" },
      take: PAGE_SIZE,
      select: {
        id: true,
        kind: true,
        status: true,
        fields: true,
        createdAt: true,
        spam: true,
      },
    }),
    db.siteRecord.count({ where: { projectId: project.id } }),
    // Every kind this project has ever collected, not just the ones on this
    // page — a kind that only appears past PAGE_SIZE must still get a tab.
    db.siteRecord.groupBy({
      by: ["kind"],
      where: { projectId: project.id },
      _count: { _all: true },
      orderBy: { kind: "asc" },
    }),
  ]);

  // `fields` is Json, so its runtime shape is whatever was written — normalise
  // to string pairs HERE rather than trusting the column, and cap what is
  // handed to the client. The write path already caps this; a second cap on
  // read costs nothing and means an old or hand-edited row cannot blow up the
  // page.
  const records: RecordRow[] = rows.map((r) => {
    const raw = r.fields;
    const pairs: [string, string][] =
      raw !== null && typeof raw === "object" && !Array.isArray(raw)
        ? Object.entries(raw)
            .slice(0, 24)
            .map(([k, v]) => [String(k).slice(0, 64), v === null ? "" : String(v).slice(0, 5000)])
        : [];
    return {
      id: r.id,
      kind: r.kind,
      status: r.status,
      fields: pairs,
      createdAt: r.createdAt.toISOString(),
      spam: r.spam,
    };
  });

  const kinds = kindCounts.map((k) => k.kind);

  return (
    // This route is inside the builder's layout, which is bare on purpose — so
    // the page carries its own canvas and its own way back, the same as the
    // editor's header and the submissions page do.
    <div className="min-h-dvh bg-canvas">
      <div className="mx-auto max-w-3xl px-4 py-8 sm:px-6 sm:py-10">
        <ButtonLink
          href={`/projects/${project.id}`}
          size="sm"
          variant="ghost"
          className="-ml-3"
          icon={
            <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round">
              <path d="M15 5 8 12l7 7" />
            </svg>
          }
        >
          {project.name}
        </ButtonLink>
        <h1 className="k-h1 mt-3 text-ink">Site records</h1>
        <p className="k-num mt-1 text-sm text-ink-2">
          {total === 0
            ? "Nothing yet."
            : `${total} total${total > PAGE_SIZE ? ` · showing the latest ${PAGE_SIZE}` : ""}`}
        </p>

        {!project.publishedAt && (
          <p className="mt-6 rounded-lg border border-hair bg-surface p-4 text-sm leading-relaxed text-ink-2">
            This site isn&apos;t published, so it can&apos;t record anything yet. Records are only
            accepted for a live site.
          </p>
        )}

        {total === 0 ? (
          <EmptyState
            className="mt-6"
            kind="empty"
            title="No records yet"
            body="When your published site writes data back through /__records/<kind>, it lands here — grouped by whatever kind it used."
          />
        ) : (
          <div className="mt-6">
            <RecordList kinds={kinds} initial={records} />
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { EmptyState } from "@/components/ui/EmptyState";
import { Segmented } from "@/components/ui/Segmented";

export type RecordRow = {
  id: string;
  kind: string;
  status: string;
  /** Ordered key/value pairs, already normalised and capped on the server. */
  fields: [string, string][];
  createdAt: string;
  spam: boolean;
};

/**
 * Every value below came from a stranger on the public internet.
 *
 * It is rendered as a React child — `{value}` — and nowhere in this file is
 * there a dangerouslySetInnerHTML, an href built from a field, or a value
 * passed to anything that would parse it. React escapes text children, so a
 * record of `<img onerror=…>` shows up as those characters. Do not "improve"
 * this by auto-linking addresses or URLs without escaping first.
 */
function Field({ name, value }: { name: string; value: string }) {
  return (
    <div className="grid grid-cols-[minmax(0,7rem)_1fr] gap-3 py-1">
      <div className="truncate text-[0.75rem] text-ink-3" title={name}>
        {name}
      </div>
      <div className="text-sm break-words whitespace-pre-wrap text-ink">{value}</div>
    </div>
  );
}

function when(iso: string): string {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleString();
}

const ALL = "__all__";

/**
 * `kind` is never a fixed list here — the tabs are built from whichever kinds
 * this project's own records actually used (page.tsx groups by kind), so a
 * generated site can invent any kind it needs and it shows up on its own.
 */
export default function RecordList({
  kinds,
  initial,
}: {
  kinds: string[];
  initial: RecordRow[];
}) {
  const [rows] = useState(initial);
  const [kind, setKind] = useState<string>(ALL);
  const [showSpam, setShowSpam] = useState(false);

  const byKind = rows.filter((r) => kind === ALL || r.kind === kind);
  const visible = byKind.filter((r) => r.spam === showSpam);
  const spamCount = byKind.filter((r) => r.spam).length;
  const activeCount = byKind.filter((r) => !r.spam).length;

  return (
    <div>
      <div className="mb-4 flex flex-wrap items-center gap-2">
        {kinds.length > 1 && (
          <Segmented
            name="kodely-record-kind"
            ariaLabel="Filter by kind"
            size="sm"
            value={kind}
            onChange={setKind}
            options={[
              { value: ALL, label: "All" },
              ...kinds.map((k) => ({ value: k, label: k })),
            ]}
          />
        )}
        <div className="grow" />
        {spamCount > 0 && (
          <Button
            size="xs"
            variant="ghost"
            className="border border-hair"
            onClick={() => setShowSpam((v) => !v)}
          >
            {showSpam ? `Records (${activeCount})` : `Filtered (${spamCount})`}
          </Button>
        )}
      </div>

      {visible.length === 0 ? (
        <EmptyState
          // `no-results` rather than `empty`: there ARE records, the current
          // filter just has none of them.
          kind="no-results"
          title={showSpam ? "Nothing filtered" : "Nothing here"}
          body={
            showSpam
              ? "Anything caught by the spam trap is kept here rather than thrown away."
              : "Everything that matches this filter has been caught by the spam trap."
          }
        />
      ) : (
        <ul className="space-y-3">
          {visible.map((r) => (
            <li key={r.id} className="rounded-lg border border-hair bg-surface p-4 shadow-e1">
              <div className="mb-2 flex flex-wrap items-center gap-2 text-[0.75rem] text-ink-3">
                <Badge tone="neutral">{r.kind}</Badge>
                {r.status !== "active" && <Badge tone="warn">{r.status}</Badge>}
                <time className="k-num" dateTime={r.createdAt}>
                  {when(r.createdAt)}
                </time>
              </div>
              {r.fields.length === 0 ? (
                <p className="text-sm text-ink-3">(empty)</p>
              ) : (
                r.fields.map(([k, v]) => <Field key={k} name={k} value={v} />)
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
